62: } f_audio = {
63: 		"audio",
64: 		"8 kHz, 8 bit u-law encoding with Sun audio header", ".au",
65: 		audio_init_input,
66: 		audio_init_output,
67: 		ulaw_input,
68: 		ulaw_output
