247: /*
248:  *  Allocate some memory and complain if it fails.
249:  */
250: static char * emalloc P1((len), size_t len)
251: {
252: 	char * s;
253: 	if (!(s = malloc(len))) {
254: 		fprintf(stderr, "%s: failed to malloc %d bytes -- abort\n",
255: 			progname, (int)len);
256: 		onintr();
257: 		exit(1);
258: 	}
259: 	return s;
260: }
