519: 				"%s: can't open \"%s\" for writing\n",
520: 				progname, o);
521: 			if (outfd >= 0) (void)close(outfd);
522: 			return 0;
523: 		}
524: 
525: 		outname = o;
526: 	}
527: 	return 1;
